  // Product Edit/Delete
  openEditProduct(product: any) {
    this.editingProductId = product.id;
    this.editForm = {
      title: product.title || '',
      shortDescription: product.shortDescription || '',
      fullDescription: product.fullDescription || '',
      price: product.price || 0,
      originalPrice: product.originalPrice || null,
      version: product.version || '',
      category: product.category || '',
      status: product.status || 'published',
      demoUrl: product.demoUrl || '',
      youtubeUrl: product.youtubeUrl || '',
      tagsStr: (product.tags || []).join(', '),
      featuresStr: (product.features || []).join('\n'),
      techStackStr: (product.techStack || []).join(', '),
      isFeatured: product.isFeatured || false,
      isBestseller: product.isBestseller || false,
      isNew: product.isNew || false,
      thumbnailPreview: product.thumbnailUrl || '',
      newThumbnailData: null,
      screenshotPreviews: [...(product.previewImages || [])],
      newScreenshotData: [] as string[],
      liveDemos: product.liveDemos ? [...product.liveDemos] : [],
    };
    this.showEditModal = true;
  }

  closeEditModal() {
    this.showEditModal = false;
    this.editingProductId = null;
    this.editForm = {};
  }

  async saveEditProduct() {
    if (!this.editingProductId || !this.editForm.title) return;
    const updates: any = {
      title: this.editForm.title,
      shortDescription: this.editForm.shortDescription,
      fullDescription: this.editForm.fullDescription,
      price: Number(this.editForm.price),
      version: this.editForm.version,
      category: this.editForm.category,
      status: this.editForm.status,
      tags: this.editForm.tagsStr.split(',').map((t: string) => t.trim()).filter((t: string) => t),
      features: this.editForm.featuresStr.split('\n').filter((f: string) => f.trim()),
      techStack: this.editForm.techStackStr.split(',').map((t: string) => t.trim()).filter((t: string) => t),
      isFeatured: this.editForm.isFeatured,
      isBestseller: this.editForm.isBestseller,
      isNew: this.editForm.isNew,
    };
    if (this.editForm.originalPrice) {
      updates.originalPrice = Number(this.editForm.originalPrice);
      updates.discountPercent = Math.round((1 - updates.price / updates.originalPrice) * 100);
    }
    if (!this.editingProductId) return;

    this.isSaving.set(true);

    try {
      // 1. Upload Thumbnail if it's new (base64)
      let thumbnailUrl = this.editForm.thumbnailPreview;
      if (thumbnailUrl && thumbnailUrl.startsWith('data:')) {
        thumbnailUrl = await this.imageUpload.upload(thumbnailUrl, 'products/thumbnails');
      }

      // 2. Upload Screenshots if they are new
      const previewImages: string[] = [];
      for (const img of this.editForm.screenshotPreviews) {
        if (img.startsWith('data:')) {
          const uploadedUrl = await this.imageUpload.upload(img, 'products/screenshots');
          previewImages.push(uploadedUrl);
        } else {
          previewImages.push(img);
        }
      }

      // 3. Upload Live Demo Thumbnails
      const liveDemos = [];
      if (this.editForm.liveDemos) {
        for (const demo of this.editForm.liveDemos) {
          let demoThumb = demo.thumbnailUrl;
          if (demoThumb && demoThumb.startsWith('data:')) {
            demoThumb = await this.imageUpload.upload(demoThumb, 'products/demos');
          }
          liveDemos.push({ ...demo, thumbnailUrl: demoThumb });
        }
      }

      const updates: any = {
        title: this.editForm.title,
        shortDescription: this.editForm.shortDescription,
        category: this.editForm.category,
        price: this.editForm.price,
        originalPrice: this.editForm.originalPrice,
        tags: this.editForm.tagsStr.split(',').map((t: string) => t.trim()).filter((t: string) => t),
        features: this.editForm.featuresStr.split('\n').filter((f: string) => f.trim()),
        techStack: this.editForm.techStackStr.split(',').map((t: string) => t.trim()).filter((t: string) => t),
        thumbnailUrl: thumbnailUrl,
        previewImages: previewImages,
        liveDemos: liveDemos,
        youtubeUrl: this.editForm.youtubeUrl || ''
      };

      // Sanitize for Firestore (handles undefined etc)
      const cleanedUpdates = this.marketplace.cleanForFirestore(updates);
      
      await this.marketplace.updateProduct(this.editingProductId, cleanedUpdates);
      
      this.closeEditModal();
      alert('Product updated successfully! All assets moved to cloud storage.');
    } catch (error) {
      console.error('Error updating product:', error);
      alert('Failed to update product assets. Check console for details.');
    } finally {
      this.isSaving.set(false);
    }
  }

  async deleteProduct(productId: string) {
    if (!confirm('Are you sure you want to permanently delete this product?')) return;
    try {
      await this.marketplace.deleteProduct(productId);
      alert('Product deleted.');
    } catch (error) {
      console.error('Error deleting product:', error);
      alert('Failed to delete product.');
    }
  }

  // Image handling for edit modal
  onEditThumbnailSelect(event: Event) {
    const input = event.target as HTMLInputElement;
    if (input.files?.length) {
      const reader = new FileReader();
      reader.onload = (e) => {
        this.editForm.thumbnailPreview = e.target?.result as string;
        this.editForm.newThumbnailData = e.target?.result as string;
      };
      reader.readAsDataURL(input.files[0]);
    }
  }

  onEditScreenshotsSelect(event: Event) {
    const input = event.target as HTMLInputElement;
    if (input.files) {
      Array.from(input.files).forEach(file => {
        const reader = new FileReader();
        reader.onload = (e) => {
          this.editForm.screenshotPreviews.push(e.target?.result as string);
        };
        reader.readAsDataURL(file);
      });
    }
  }

  removeEditScreenshot(index: number) {
    this.editForm.screenshotPreviews = this.editForm.screenshotPreviews.filter((_: any, i: number) => i !== index);
  }

  // Live Demo Management
  addEditDemo() {
    this.editForm.liveDemos.push({ label: '', url: '', thumbnailUrl: '' });
  }

  removeEditDemo(index: number) {
    this.editForm.liveDemos.splice(index, 1);
  }

  onDemoThumbnailSelect(event: Event, index: number) {
    const input = event.target as HTMLInputElement;
    if (input.files?.length) {
      const reader = new FileReader();
      reader.onload = (e) => {
        this.editForm.liveDemos[index].thumbnailUrl = e.target?.result as string;
      };
      reader.readAsDataURL(input.files[0]);
    }
  }

  // Blog Management Methods
  analyticsEvents: any[] = [];
  
  async loadAnalytics() {
    try {
      const analyticsRef = collection(this.firestore, 'site_analytics');
      const q = query(analyticsRef, orderBy('timestamp', 'desc'));
      collectionData(q, { idField: 'id' }).subscribe((events: any) => {
        this.analyticsEvents = events.map((ev: any) => ({
          ...ev,
          timestamp: ev.timestamp?.toDate?.() || new Date(ev.timestamp)
        }));
      });
    } catch(e) {
      console.error('Failed to load analytics', e);
    }
  }

  async loadBlogs() {
    try {
      const blogsRef = collection(this.firestore, 'Blogs');
      const q = query(blogsRef, orderBy('createdAt', 'desc'));
      collectionData(q, { idField: 'id' }).subscribe((data: any) => {
        this.blogs = data.map((blog: any) => ({
          ...blog,
          createdAt: blog.createdAt?.toDate?.() || new Date(blog.createdAt)
        }));
      });
    } catch (error) {
      console.error('Error loading blogs:', error);
      this.blogs = [];
    }
  }

